import React, { useState, useEffect } from 'react';
import { fetchData } from './api/client';

export const App: React.FC = () => {
  const [data, setData] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const loadData = async () => {
      try {
        const result = await fetchData();
        setData(result);
      } catch (error) {
        console.error('Error loading data:', error);
      } finally {
        setLoading(false);
      }
    };
    loadData();
  }, []);

  if (loading) return <div>Loading...</div>;
  return <div>{data?.title}</div>;
};

import axios from 'axios';

const client = axios.create({
  baseURL: process.env.REACT_APP_API_URL,
  timeout: 5000,
});

export async function fetchData() {
  try {
    const response = await client.get('/api/data');
    return response.data;
  } catch (error) {
    throw new Error(`API Error: ${error}`);
  }
}

export async function postData(payload: unknown) {
  const response = await client.post('/api/data', payload);
  return response.data;
}

import React from 'react';

interface HeaderProps {
  title: string;
  onNavigate?: (path: string) => void;
}

/**
 * Header component for page navigation
 */
export const Header: React.FC<HeaderProps> = ({ title, onNavigate }) => {
  return (
    <header className="header">
      <h1>{title}</h1>
      <nav>
        <button onClick={() => onNavigate?.('/')}>Home</button>
        <button onClick={() => onNavigate?.('/about')}>About</button>
      </nav>
    </header>
  );
};

import { describe, it, expect } from '@jest/globals';
import { validate, sanitize } from './validation';

describe('validation', () => {
  it('should validate email addresses', () => {
    expect(validate.email('test@example.com')).toBe(true);
    expect(validate.email('invalid')).toBe(false);
  });

  it('should sanitize user input', () => {
    expect(sanitize('<script>alert(1)</script>')).toBe('');
    expect(sanitize('normal text')).toBe('normal text');
  });
});

export class AuthService {
  async login(username: string, password: string) {
    try {
      const response = await fetch('/api/auth/login', {
        method: 'POST',
        body: JSON.stringify({ username, password }),
      });
      return response.json();
    } catch (error) {
      console.error('Login failed:', error);
      throw error;
    }
  }

  async logout() {
    return fetch('/api/auth/logout', { method: 'POST' });
  }
}

export class PaymentService {
  async processPayment(amount: number, cardToken: string) {
    try {
      const response = await fetch('/api/payments/process', {
        method: 'POST',
        body: JSON.stringify({ amount, cardToken }),
      });
      if (!response.ok) throw new Error('Payment failed');
      return response.json();
    } catch (error) {
      throw new Error(`Payment error: ${error}`);
    }
  }
}
